def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def as_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        if isinstance(v, dict):
            if "x" in v and "y" in v and is_num(v.get("x")) and is_num(v.get("y")):
                return [int(v.get("x")), int(v.get("y"))]
            if "row" in v and "col" in v and is_num(v.get("row")) and is_num(v.get("col")):
                return [int(v.get("row")), int(v.get("col"))]
        return None

    def first_pair_from_keys(obj, keys):
        if not isinstance(obj, dict):
            return None
        for k in keys:
            p = as_pair(obj.get(k))
            if p is not None:
                return p
        return None

    def collect_pairs(obj, out, limit=128):
        if len(out) >= limit:
            return
        p = as_pair(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_pairs(v, out, limit)
                if len(out) >= limit:
                    return
        elif isinstance(obj, (list, tuple, set)):
            for v in obj:
                collect_pairs(v, out, limit)
                if len(out) >= limit:
                    return

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(x):
        if x > 1:
            return 1
        if x < -1:
            return -1
        return int(x)

    obs = observation if isinstance(observation, dict) else {}

    me = first_pair_from_keys(obs, ("position", "pos", "self_pos", "agent_pos", "location", "loc", "coord", "coordinates"))
    if me is None:
        me = first_pair_from_keys(obs.get("self", {}) if isinstance(obs.get("self", {}), dict) else {}, ("position", "pos", "location", "loc"))
    if me is None:
        return [0, 0]

    resources = []
    enemies = []
    territory = []
    allies = []
    threats = []

    for key in ("resources", "resource_positions", "food", "targets", "goals", "collectibles"):
        collect_pairs(obs.get(key), resources)

    for key in ("enemies", "opponents", "adversaries", "enemy_positions"):
        collect_pairs(obs.get(key), enemies)

    for key in ("territory", "frontier", "unclaimed", "capture_points", "cells", "objective"):
        collect_pairs(obs.get(key), territory)

    for key in ("allies", "teammates", "friends"):
        collect_pairs(obs.get(key), allies)

    collect_pairs(obs.get("threats"), threats)
    for p in threats:
        enemies.append(p)

    # Deduplicate while preserving order
    def dedup(seq):
        seen = {}
        out = []
        for p in seq:
            t = (p[0], p[1])
            if t not in seen:
                seen[t] = True
                out.append(p)
        return out

    resources = dedup(resources)
    enemies = dedup(enemies)
    territory = dedup(territory)
    allies = dedup(allies)

    # Determine if we should flee
    flee = False
    if enemies:
        nearest_enemy = min(enemies, key=lambda p: manhattan(me, p))
        if manhattan(me, nearest_enemy) <= 1:
            flee = True

    legal = None
    for key in ("legal_moves", "moves", "action_mask", "valid_moves"):
        val = obs.get(key)
        if isinstance(val, (list, tuple, set, dict)):
            legal = val
            break

    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            candidates.append([dx, dy])

    def allowed(move):
        if legal is None:
            return True
        dx, dy = move
        if isinstance(legal, dict):
            if (dx, dy) in legal:
                return bool(legal.get((dx, dy)))
            s = str((dx, dy))
            if s in legal:
                return bool(legal.get(s))
            return True
        if isinstance(legal, (list, tuple)):
            if len(legal) == 9 and all(isinstance(x, (int, bool)) for x in legal):
                idx = (dx + 1) * 3 + (dy + 1)
                return bool(legal[idx])
            return True
        if isinstance(legal, set):
            return (dx, dy) in legal
        return True

    best_move = [0, 0]
    best_score = None

    # Center bias if map size known
    center = None
    for dims_key in ("map_size", "board_size", "size", "dimensions"):
        dims = obs.get(dims_key)
        if isinstance(dims, (list, tuple)) and len(dims) >= 2 and is_num(dims[0]) and is_num(dims[1]):
            center = [int(dims[0]) // 2, int(dims[1]) // 2]
            break

    for move in candidates:
        if not allowed(move):
            continue
        nx = me[0] + move[0]
        ny = me[1] + move[1]
        score = 0.0

        if flee and enemies:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += d * 10.0
            score -= manhattan([nx, ny], nearest_enemy) * 2.0
        elif resources:
            d = min(manhattan([nx, ny], r) for r in resources)
            score += -d * 10.0
        elif territory:
            d = min(manhattan([nx, ny], t) for t in territory)
            score += -d * 6.0
        elif enemies:
            d = min(manhattan([nx, ny], e) for e in enemies)
            score += -d * 2.0

        if center is not None:
            score += -0.1 * manhattan([nx, ny], center)

        # Mild preference for movement over standing still
        if move != [0, 0]:
            score += 0.05

        # Tie-breaker: deterministic lexicographic preference
        tie = move[0] * 10 + move[1]
        if best_score is None or score > best_score or (score == best_score and tie > (best_move[0] * 10 + best_move[1])):
            best_score = score
            best_move = move

    dx = clamp_step(best_move[0])
    dy = clamp_step(best_move[1])
    return [dx, dy]

